import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFlow Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFlow/aireflow-v2-41-0.md","filePath":"aireblock-releases/AireFlow/aireflow-v2-41-0.md","lastUpdated":1789463877000}`),a={name:`aireblock-releases/AireFlow/aireflow-v2-41-0.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireflow-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireflow-icon.png"> AireFlow Release Notes</span> <a class="header-anchor" href="#aireflow-release-notes" aria-label="Permalink to “AireFlow Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> v2.41.0<br><strong>Release Date:</strong> 23 September 2026</p></blockquote><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Expanded Owner and Assignee Type Options (FLOW-1331)</li><li>Smarter HTTP Request Body Validation (FLOW-1299)</li><li>Direct Access to Configurator&#39;s Vault UI (FLOW-1356)</li></ul><h4 id="🔧-tasks" tabindex="-1">🔧 Tasks <a class="header-anchor" href="#🔧-tasks" aria-label="Permalink to “🔧 Tasks”">​</a></h4><ul><li>Faster, More Reliable Pagination (FLOW-1102)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Updated Vulnerable JavaScript Libraries (FLOW-1318)</li><li>Fixed Verbose Server Error Messages (FLOW-1323)</li><li>Fixed Task Patch API Crash (FLOW-1351)</li><li>Fixed Incorrect API Key Policy Caching (FLOW-1355)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="expanded-owner-and-assignee-type-options-flow-1331" tabindex="-1">Expanded Owner and Assignee Type Options (FLOW-1331) <a class="header-anchor" href="#expanded-owner-and-assignee-type-options-flow-1331" aria-label="Permalink to “Expanded Owner and Assignee Type Options (FLOW-1331)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Owner Type and Assignee Type fields have been aligned with AireFrame, adding support for the full set of identifier types (User, Subject, Subject Proxy, External, Client Credentials, System and Unknown) via a dropdown, with a toggle to switch to free text. As part of this change, the Owner Type field on the API has moved from a fixed list of values to a plain string.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When setting an owner or assignee on a task, you can now choose from the same full range of options available in AireFrame, including client credentials, rather than being limited to a shorter dropdown or free text only.</p></div><h4 id="smarter-http-request-body-validation-flow-1299" tabindex="-1">Smarter HTTP Request Body Validation (FLOW-1299) <a class="header-anchor" href="#smarter-http-request-body-validation-flow-1299" aria-label="Permalink to “Smarter HTTP Request Body Validation (FLOW-1299)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The HTTP Request Task body field is now validated against the content type you select, with support for automatically closing quotes, brackets and tags, and highlighting invalid syntax. Liquid templating syntax is recognised and is no longer flagged as invalid.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When building HTTP Request tasks, you&#39;ll get immediate, inline feedback if your request body doesn&#39;t match the format you&#39;ve selected, making it easier to spot and fix mistakes before you save.</p></div><h4 id="direct-access-to-configurator-s-vault-ui-flow-1356" tabindex="-1">Direct Access to Configurator&#39;s Vault UI (FLOW-1356) <a class="header-anchor" href="#direct-access-to-configurator-s-vault-ui-flow-1356" aria-label="Permalink to “Direct Access to Configurator&#39;s Vault UI (FLOW-1356)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Links that previously pointed to the Vault API now open Configurator&#39;s Vault UI in a new window instead, signed in with the same tenant so you can view the current tenant&#39;s variables and secrets directly.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now jump straight into a readable, browsable view of your vault variables and secrets, instead of being shown a raw API response.</p></div><h3 id="🔧-tasks-1" tabindex="-1">🔧 Tasks <a class="header-anchor" href="#🔧-tasks-1" aria-label="Permalink to “🔧 Tasks”">​</a></h3><hr><h4 id="faster-more-reliable-pagination-flow-1102" tabindex="-1">Faster, More Reliable Pagination (FLOW-1102) <a class="header-anchor" href="#faster-more-reliable-pagination-flow-1102" aria-label="Permalink to “Faster, More Reliable Pagination (FLOW-1102)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Keyset-based pagination has been implemented for the UI and the AireFrame data provider, replacing offset-based paging, which could produce inconsistent results such as skipped or duplicated records on large or frequently changing lists. Offset-based pagination remains available on the API for backwards compatibility.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="updated-vulnerable-javascript-libraries-flow-1318" tabindex="-1">Updated Vulnerable JavaScript Libraries (FLOW-1318) <a class="header-anchor" href="#updated-vulnerable-javascript-libraries-flow-1318" aria-label="Permalink to “Updated Vulnerable JavaScript Libraries (FLOW-1318)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Several third-party JavaScript libraries served by AireFlow, including DOMPurify, React, GraphQL, core-js, uuid, highlight.js and Autolinker, were flagged with known vulnerabilities during penetration testing. Dependencies have been reviewed and updated where possible to reduce the application&#39;s exposure.</p></div><h4 id="fixed-verbose-server-error-messages-flow-1323" tabindex="-1">Fixed Verbose Server Error Messages (FLOW-1323) <a class="header-anchor" href="#fixed-verbose-server-error-messages-flow-1323" aria-label="Permalink to “Fixed Verbose Server Error Messages (FLOW-1323)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The API was returning detailed technical error messages, including deserialisation error details, when malformed input was submitted. These verbose messages have been suppressed so that internal implementation details are no longer exposed in error responses.</p></div><h4 id="fixed-task-patch-api-crash-flow-1351" tabindex="-1">Fixed Task Patch API Crash (FLOW-1351) <a class="header-anchor" href="#fixed-task-patch-api-crash-flow-1351" aria-label="Permalink to “Fixed Task Patch API Crash (FLOW-1351)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Sending a PATCH request to update a task could intermittently fail with a null reference error, returning a 500 response. This has been fixed so that task updates via the API complete reliably.</p></div><h4 id="fixed-incorrect-api-key-policy-caching-flow-1355" tabindex="-1">Fixed Incorrect API Key Policy Caching (FLOW-1355) <a class="header-anchor" href="#fixed-incorrect-api-key-policy-caching-flow-1355" aria-label="Permalink to “Fixed Incorrect API Key Policy Caching (FLOW-1355)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Authorisation policies were being cached incorrectly when authenticating with an API key, which could result in the wrong access policy being applied. Policy caching for API key authentication has been corrected.</p></div>`,34)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};